def gen_value(name, profile, rng, PII_META):
    fmt = (PII_META.get(name) or {}).get('format') or {}
    strat = fmt.get('gen_strategy')
    if strat in ('categorical','template_pool'):
        pool = fmt.get('value_pool') or fmt.get('value_templates') or []
        w = fmt.get('weights')
        tmpl = weighted_choice(dict(zip(pool,w)), rng) if w else rng.choice(pool)
        return fill_placeholders(tmpl, profile, rng, fmt.get('placeholders'))
    if strat == 'structured':
        return build_structured(name, fmt['builder'], profile, rng)  # cccd/gplx suy digit từ dob+gender
    ...
